#!/usr/bin/env bash
# Droit à l'image : destination des galeries et du carrousel ; un refus d'une personne taguée bloque et masque.
# Prérequis : apply-docs-tags-tableau.sh. Pas de migration.
# Usage (racine du repo) : bash apply-fix-tags-destinations.sh
set -euo pipefail
cd "$(dirname "$0")"
[ -f pnpm-workspace.yaml ] || { echo "À lancer à la racine du repo."; exit 1; }

if git show HEAD:"packages/contracts/src/legal/mediaPeople.ts" 2>/dev/null | grep -qF "export function galleryDestinations"; then echo "Déjà appliqué (commité)."; exit 0; fi
grep -qF "## La modale des tags" "apps/web/content/docs/dev/legal/tags-de-personnes.mdx" 2>/dev/null || { echo "❌ lancer d'abord apply-fix-tags-tableau.sh puis apply-docs-tags-tableau.sh"; exit 1; }
MODIFIED=("apps/web/src/app/(admin)/dashboard/galleries/[id]/edit/page.tsx" "apps/web/src/app/(admin)/dashboard/galleries/[id]/page.tsx" "apps/web/src/features/admin/galleries/actions/createGalleryForm.action.ts" "apps/web/src/features/admin/galleries/actions/updateGalleryForm.action.ts" "apps/web/src/features/admin/galleries/components/GalleriesTable.tsx" "apps/web/src/features/admin/galleries/components/GalleryItemsManager.tsx" "apps/web/src/features/admin/galleries/components/MediaItemsEditor.tsx" "apps/web/src/features/admin/galleries/forms/CreateGalleryForm.tsx" "e2e/data.mjs" "e2e/prepare.mjs" "packages/backend/src/modules/galleries/router.ts" "packages/backend/src/modules/mediaPeople/mediaPeople.service.ts" "packages/contracts/src/legal/mediaPeople.ts")
CREATED=("apps/web/src/features/admin/media-people/RightsCheckBanner.tsx" "e2e/droit-a-l-image-destinations.spec.ts")
restore(){ git checkout -q -- "${MODIFIED[@]}" 2>/dev/null || true; rm -f "${CREATED[@]}"; echo "  ↩ fichiers restaurés"; }
if grep -qF "export function galleryDestinations" "packages/contracts/src/legal/mediaPeople.ts" 2>/dev/null; then echo "  restes d'un essai précédent non commité → nettoyage"; restore; fi
if ! git diff --quiet HEAD -- "${MODIFIED[@]}" 2>/dev/null; then echo "❌ modifications non commitées dans des fichiers que ce script modifie (rien n'a été touché) :"; git diff --name-only HEAD -- "${MODIFIED[@]}" | head -5; exit 1; fi
trap 'restore' ERR

mkdir -p "apps/web/src/features/admin/media-people"
